SELECT a.account_type, a.status, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(t.txn_type))) AS txn_type_values, SUM(CASE WHEN t.merchant = 'Grab' THEN t.amount ELSE 0 END) AS grab_amount FROM transactions t INNER JOIN accounts a ON a.id = t.account_id LEFT JOIN customers c ON a.customer_id = c.id WHERE MONTH(a.opened_date) IN (4, 5, 9) GROUP BY a.account_type, a.status ORDER BY status, account_type LIMIT 20;
